define('APP_INIT',true);
require_once __DIR__.'/../config/app.php'; require_once ROOT_PATH.'/includes/auth_check.php'; require_once ROOT_PATH.'/includes/platform_check.php'; requirePlatformAdmin();
$db=Database::getConnection(); $plans=$db->query('SELECT * FROM subscription_plans ORDER BY display_order,id')->fetchAll(); $csrf=getCsrfToken();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Manage plans</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#070914;color:#f5f5ff}.card{background:#151a2a;border:1px solid #363c60;color:#f5f5ff}.form-control{background:#0c1020;color:#fff;border-color:#464e75}.form-control:focus{background:#0c1020;color:#fff}.muted{color:#adb4cb}.violet{background:linear-gradient(90deg,#6d28d9,#a855f7);border:0}</style></head><body><main class="container py-5"><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h3 mb-1">Subscription plans</h1><p class="muted mb-0">Edit prices and limits, or safely delete/archive a plan.</p></div><a class="btn btn-outline-light" href="<?=BASE_URL?>/admin/manage.php">Back to platform</a></div><div id="notice"></div><?php foreach($plans as $plan):?><form class="card p-4 mb-3 plan-form"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($csrf)?>"><input type="hidden" name="id" value="<?=$plan['id']?>"><input type="hidden" name="status" value="<?=htmlspecialchars($plan['status'])?>"><div class="row g-3 align-items-end"><div class="col-md-2"><label class="form-label">Code</label><input class="form-control" name="code" value="<?=htmlspecialchars($plan['code'])?>" required></div><div class="col-md-2"><label class="form-label">Name</label><input class="form-control" name="name" value="<?=htmlspecialchars($plan['name'])?>" required></div><div class="col-md-2"><label class="form-label">Monthly ৳</label><input class="form-control" name="price" type="number" min="0" step=".01" value="<?=$plan['price']?>"></div><div class="col-md-2"><label class="form-label">Yearly ৳</label><input class="form-control" name="yearly_price" type="number" min="0" step=".01" value="<?=$plan['yearly_price']?>"></div><div class="col-md-1"><label class="form-label">Trial</label><input class="form-control" name="trial_days" type="number" min="0" value="<?=$plan['trial_days']?>"></div><div class="col-md-1"><label class="form-label">Companies</label><input class="form-control" name="company_limit" type="number" min="0" value="<?=htmlspecialchars((string)($plan['company_limit']??''))?>"></div><div class="col-md-1"><label class="form-label">Products</label><input class="form-control" name="product_limit" type="number" min="0" value="<?=htmlspecialchars((string)($plan['product_limit']??''))?>"></div><div class="col-md-1"><label class="form-label">Customers</label><input class="form-control" name="customer_limit" type="number" min="0" value="<?=htmlspecialchars((string)($plan['customer_limit']??''))?>"></div><div class="col-md-1"><label class="form-label">Users</label><input class="form-control" name="user_limit" type="number" min="0" value="<?=htmlspecialchars((string)($plan['user_limit']??''))?>"></div><div class="col-12"><button class="btn violet text-white">Save changes</button> <button class="btn btn-outline-danger delete-plan" type="button" data-id="<?=$plan['id']?>">Delete / archive</button><span class="muted small ms-2">Status: <?=htmlspecialchars($plan['status'])?></span></div></div></form><?php endforeach?></main><script>const notice=document.querySelector('#notice');function show(ok,m){notice.innerHTML='<div class="alert '+(ok?'alert-success':'alert-danger')+'">'+m+'</div>';scrollTo({top:0,behavior:'smooth'})}async function send(url,data){return (await fetch(url,{method:'POST',body:data})).json()}document.querySelectorAll('.plan-form').forEach(f=>f.onsubmit=async e=>{e.preventDefault();let x=await send('<?=BASE_URL?>/ajax/platform/save_plan.php',new FormData(f));show(x.success,x.message)});document.querySelectorAll('.delete-plan').forEach(b=>b.onclick=async()=>{if(!confirm('Delete this plan? Plans already assigned to businesses will be archived instead.'))return;let f=new FormData();f.append('csrf_token',<?=json_encode($csrf)?>);f.append('id',b.dataset.id);let x=await send('<?=BASE_URL?>/ajax/platform/delete_plan.php',f);show(x.success,x.message);if(x.success)setTimeout(()=>location.reload(),500)});</script></body></html>
